// The groups of the sidebar, in order: one folder of src/content/docs/ each.
// The pages come from switchback/docs/users/. A page sets its place in its
// group with `sidebar.order` in its frontmatter. A group with `items` lists
// its pages and subfolders itself, because Starlight names an autogenerated
// subfolder group after its folder.
export const groups = [
  { label: 'Start here', directory: 'start-here' },
  {
    label: 'Guides',
    directory: 'guides',
    items: [
      { slug: 'guides/receipts' },
      { label: 'CLI', collapsed: true, items: [{ autogenerate: { directory: 'guides/cli' } }] },
    ],
  },
  {
    label: 'Admin',
    directory: 'admin',
    items: [
      { slug: 'admin/invite-teammates' },
      { label: 'Integrations', items: [{ autogenerate: { directory: 'admin/integrations' } }] },
    ],
  },
  { label: 'Security', directory: 'security' },
  { label: 'Resources', directory: 'resources' },
];
